async loadGraphic(settings, graphicPath, data) {
	// Clear any existing GraphicInstance:

	if (this.currentGraphic) {
		this.clearGraphic()
	}

	this.lastGoToTime = undefined

	const { elementName, customControllers } = await ResourceProvider.loadGraphicModule(graphicPath)

	// Add element to DOM:
	const element = document.createElement(elementName)
	element.setAttribute('drawable', '')
	element.style.display = 'block'
	element.style.width = '100%'
	element.style.height = '100%'
	this.shadowRoot.appendChild(element)

	this.currentGraphic = {
		element,
		elementName,
		graphicPath,
	}
	this.customControllers = customControllers || []

	// const baseUrl = graphicResourcePath(graphicPath)
	// 	// Remove last "/":
	// 	.replace(/\/$/, '')

	console.log('Loading graphic element...', data)

	// Load the element:
	await element.load({
		// baseUrl: baseUrl, // `${this.graphicCache.serverApiUrl}/serverApi/v1/graphics/graphic/${id}/${version}`, // /resources/:localPath
		renderType: settings.realtime ? 'realtime' : 'non-realtime',
		data: data,
		renderCharacteristics: {
			resolution: {
				width: settings.width,
				height: settings.height,
			},
			// frameRate: 60,

			// Vendor-specific:
			_environment: 'OGraf DevTool',
		},
	})
}
async clearGraphic() {
	console.log('Clearing graphic...')
	this.lastGoToTime = undefined
	this.pendingGoToTime = undefined
	this.isSeeking = false
	this.currentSeekPromise = null
	if (!this.currentGraphic) return
	try {
		await this.currentGraphic.element.dispose({})
	} catch (err) {
		console.error('Error disposing GraphicInstance:', err)
	} finally {
		this.shadowRoot.innerHTML = ''
		this.currentGraphic = null
		this.customControllers = []
	}
}

rendererLoad:
/** Instantiate a Graphic on a RenderTarget. Returns when the load has finished. */
async loadGraphic(settings, data) {
	if (data !== undefined) this.data = data
	if (this.graphicState === 'pre-load') {
		// Already in the process of loading, wait or return
		return
	}

	const mainFile = this.graphic?.manifest?.main || this.graphic?.main || 'graphic.mjs'
	const folderPath = this.graphic?.folderPath || this.graphic?.path || ''
	const graphicPath = ResourceProvider.graphicPath(folderPath, mainFile)

	return this._runAction('loadGraphic', { settings, data: this.data, graphicPath }, async () => {
		try {
			this.graphicState = 'pre-load'
			this.loadGraphicStartTime = Date.now()
			await this.layer.loadGraphic(settings, graphicPath, this.data)
			this.graphicState = 'post-load'
			this.loadGraphicEndTime = Date.now()
			return this.getCustomControllers()
		} catch (e) {
			this.graphicState = 'error'
			console.error(e)
			throw e
		}
	})
}

rendererClear:
/** Clear/unloads a GraphicInstance on a RenderTarget */
async clearGraphic() {
	return this._runAction('clearGraphic', {}, async () => {
		try {
			this.graphicState = 'pre-clear'
			this.clearGraphicStartTime = Date.now()
			await this.layer.clearGraphic()
			this.graphicState = 'post-clear'
			this.clearGraphicEndTime = Date.now()
		} catch (e) {
			this.graphicState = 'error'
			console.error(e)
			throw e
		}
	})
}

reload:
const reloadGraphic = React.useCallback(async () => {
	await rendererRef.current.clearGraphic()
	setCustomControllers([])
	issueTracker.clear()
	const manifest = await reloadGraphicManifest()

	if (rendererRef.current) {
		rendererRef.current.setGraphic({ ...graphic, manifest })
	}

	// Extract initialData from scheduleRef or manifest schema
	const initialEv = scheduleRef.current.find(
		(item) => item.action?.type === 'initialData' || (item.timestamp === 0 && item.action?.type === 'updateAction')
	)
	let initialData = initialEv?.action?.params?.data
	if (!initialData && manifest?.schema) {
		initialData = getDefaultDataFromSchema(manifest.schema)
	}
	if (!initialData) initialData = {}

	rendererRef.current.setData(initialData)
	setRealtimeData(initialData)
	const controllers = await rendererRef.current.loadGraphic(settingsRef.current, initialData).catch(issueTracker.addError)
	setCustomControllers(controllers || rendererRef.current.getCustomControllers())
	setGraphicReloadKey((k) => k + 1)

	setIsReloading(true)
}, [graphic, reloadGraphicManifest])

